}

/* Global Theme */
:root {
  --bg-surface: #ffffff;
  --text-primary: #000000;
}
[data-theme="dark"] {
  --bg-surface: #121212;
  --text-primary: #ffffff;
}

/* Component Usage */
.card {
  background: var(--bg-surface);
  color: var(--text-primary);
}

/* Option A: Interpolation */
const Button = styled.button`
  background: ${props => props.theme.colors.primary};
`;

/* Option B: CSS Variables */
const Button = styled.button`
  background: var(--color-action-primary);
`;

/* Design Tokens */
--color-text-link: #3b82f6; /* Blue */
